package com.commercecore.wishlist;
import com.commercecore.cart.*;import com.commercecore.common.exception.ApiException;import com.commercecore.product.*;import com.commercecore.user.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service public class WishlistService{private final WishlistItemRepository items;private final UserAccountRepository users;private final SellableItemResolver resolver;private final CartService cart;
 public WishlistService(WishlistItemRepository i,UserAccountRepository u,SellableItemResolver r,CartService c){items=i;users=u;resolver=r;cart=c;}
 @Transactional(readOnly=true)public WishlistDtos.WishlistResponse get(UUID userId){return response(userId);}
 @Transactional public WishlistDtos.WishlistResponse add(UUID userId,WishlistDtos.AddRequest request){SellableItemResolver.Selection selection=resolver.resolve(request.productId(),request.variantId(),1,false);Optional<WishlistItem> existing=selection.variant()==null?items.findByUserIdAndProductIdAndVariantIsNull(userId,selection.product().getId()):items.findByUserIdAndVariantId(userId,selection.variant().getId());if(existing.isEmpty()){UserAccount user=users.findById(userId).orElseThrow();try{items.saveAndFlush(new WishlistItem(user,selection.product(),selection.variant()));}catch(DataIntegrityViolationException ignored){}}return response(userId);}
 @Transactional public WishlistDtos.WishlistResponse remove(UUID userId,UUID id){WishlistItem item=owned(id,userId);items.delete(item);items.flush();return response(userId);}
 @Transactional public CartDtos.CartResponse moveToCart(UUID userId,UUID id,int quantity){WishlistItem item=owned(id,userId);CartDtos.CartResponse result=cart.add(userId,new CartDtos.AddItemRequest(item.getProduct().getId(),item.getVariant()==null?null:item.getVariant().getId(),quantity));items.delete(item);return result;}
 private WishlistItem owned(UUID id,UUID userId){return items.findByIdAndUserId(id,userId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"WISHLIST_ITEM_NOT_FOUND","Wishlist item was not found."));}
 private WishlistDtos.WishlistResponse response(UUID userId){return new WishlistDtos.WishlistResponse(items.findAllByUserIdOrderByCreatedAtAsc(userId).stream().map(i->{Product p=i.getProduct();ProductVariant v=i.getVariant();var state=resolver.inspect(p,v,1);return new WishlistDtos.ItemResponse(i.getId(),p.getId(),v==null?null:v.getId(),p.getName(),v==null?p.getSku():v.getSku(),(v==null?p.effectivePrice():v.effectivePrice()).setScale(2,RoundingMode.HALF_UP),state.status(),i.getCreatedAt());}).toList());}
}
